const item = $input.first().json;
const errors = [];
function text(value) {
  return value === null || value === undefined ? '' : String(value).trim();
}
const location = text(item.location);
const startDate = text(item.startDate);
const endDate = text(item.endDate);
const startTime = text(item.startTime || '10:00');
const endTime = text(item.endTime || '10:00');
const country = text(item.country || 'US') || 'US';
const dataTableId = text(item.dataTableId);
const baseUrl = text(item.baseUrl || 'https://api.apify.com/v2').replace(/\/+$/, '');
const driverAge = Number(item.driverAge);
const maxItems = Number(item.maxItems);
const maxAvailabilityDays = Number(item.maxAvailabilityDays);
const mode = text(item.mode);
const dateRe = /^\d{4}-\d{2}-\d{2}$/;
const timeRe = /^(\d{2}):(\d{2})$/;
function validDate(value) {
  if (!dateRe.test(value)) return false;
  const parsed = new Date(value + 'T00:00:00Z');
  return !Number.isNaN(parsed.getTime()) && parsed.toISOString().slice(0, 10) === value;
}
function validTime(value) {
  const match = timeRe.exec(value);
  if (!match) return false;
  const hour = Number(match[1]);
  const minute = Number(match[2]);
  return hour >= 0 && hour <= 23 && minute >= 0 && minute <= 59;
}
if (!location) errors.push('Enter a location such as Los Angeles, CA, USA.');
if (!validDate(startDate)) errors.push('startDate must be YYYY-MM-DD.');
if (!validDate(endDate)) errors.push('endDate must be YYYY-MM-DD.');
if (validDate(startDate) && validDate(endDate) && endDate < startDate) errors.push('endDate must be on or after startDate.');
if (!validTime(startTime)) errors.push('startTime must be HH:MM in 24-hour time.');
if (!validTime(endTime)) errors.push('endTime must be HH:MM in 24-hour time.');
if (!Number.isInteger(driverAge) || driverAge < 18 || driverAge > 100) errors.push('driverAge must be a whole number from 18 to 100.');
if (!Number.isInteger(maxItems) || maxItems < 1) errors.push('maxItems must be a whole number of at least 1. This template does not send 0, because 0 removes the actor cap.');
if (maxItems > item.itemCeiling) errors.push('maxItems is above this template ceiling of ' + item.itemCeiling + '. Raise itemCeiling in Trip settings only after checking the actor price.');
if (mode === 'availability') {
  if (!Number.isInteger(maxAvailabilityDays) || maxAvailabilityDays < 1 || maxAvailabilityDays > 31) {
    errors.push('maxAvailabilityDays must be a whole number from 1 to 31.');
  }
}
if (!dataTableId) errors.push('Enter the n8n data table ID. Create the table and columns before running.');
if (!/^https?:\/\/[^/\s]+/.test(baseUrl)) errors.push('baseUrl must start with http:// or https:// and must not contain a token.');
if (/token=|apify_api_/i.test(baseUrl)) errors.push('Do not put an API token in baseUrl. Use Header Auth.');
const actorInput = {
  locations: [location],
  startDate,
  endDate,
  startTime,
  endTime,
  driverAge,
  country,
  maxItems,
  includeCarDetails: false,
  includeCarReviews: false,
  includeHost: false,
  includeHostReviews: false,
  includeAvailability: mode === 'availability',
};
if (mode === 'availability') actorInput.maxAvailabilityDays = maxAvailabilityDays;
return [{
  json: {
    decision: errors.length ? 'invalid' : 'valid',
    errors,
    actorInput,
    baseUrl,
    dataTableId,
    location,
    startDate,
    endDate,
    startTime,
    endTime,
    driverAge: String(driverAge),
    mode,
    pageSize: 10,
    maxPolls: 60,
    pollWaitSeconds: 10,
    maxPages: 20,
  },
}];

const http = $input.first().json;
let body = http.body;
if (typeof body === 'string') {
  try { body = JSON.parse(body); } catch (error) { body = {}; }
}
if (!body || typeof body !== 'object') body = {};
const data = body.data && typeof body.data === 'object' ? body.data : body;
const runId = data && data.id ? String(data.id) : '';
const statusCode = Number(http.statusCode || 0);
const state = $('Validate settings').first().json;
const accepted = Boolean(runId) && (statusCode === 0 || (statusCode >= 200 && statusCode < 300));
let message = 'Actor run did not return a run id. Do not start another run until you check Apify for a run created at this time.';
if (body.error && body.error.message) message = String(body.error.message).slice(0, 500);
return [{
  json: {
    decision: accepted ? 'accepted' : 'rejected',
    runId,
    datasetId: data && data.defaultDatasetId ? String(data.defaultDatasetId) : '',
    statusCode,
    message,
    baseUrl: state.baseUrl,
    dataTableId: state.dataTableId,
    actorInput: state.actorInput,
    location: state.location,
    startDate: state.startDate,
    endDate: state.endDate,
    driverAge: state.driverAge,
    pageSize: state.pageSize,
    maxPolls: state.maxPolls,
    pollWaitSeconds: state.pollWaitSeconds,
    maxPages: state.maxPages,
    mode: state.mode,
    pollCount: 0,
    cars: [],
    fetched: 0,
    blockedInTrip: 0,
    openInTrip: 0,
    calendarDays: 0,
  },
}];

const item = $input.first().json;
const pollCount = Number.isInteger(item.pollCount) ? item.pollCount : 0;
return [{ json: { ...item, pollCount } }];

const http = $input.first().json;
const state = $('Wait for run').item.json;
let body = http.body;
if (typeof body === 'string') {
  try { body = JSON.parse(body); } catch (error) { body = {}; }
}
if (!body || typeof body !== 'object') body = {};
const data = body.data && typeof body.data === 'object' ? body.data : {};
const status = data.status ? String(data.status) : '';
const pollCount = Number(state.pollCount || 0) + 1;
const terminal = {
  SUCCEEDED: 'succeeded',
  FAILED: 'failed',
  ABORTED: 'aborted',
  'TIMED-OUT': 'timed_out',
};
let decision = terminal[status] || 'keep_polling';
if (!status) decision = 'poll_error';
if (decision === 'keep_polling' && pollCount >= Number(state.maxPolls)) decision = 'poll_deadline';
const datasetId = data.defaultDatasetId ? String(data.defaultDatasetId) : (state.datasetId || '');
return [{
  json: {
    ...state,
    decision,
    pollCount,
    runStatus: status,
    datasetId,
    statusMessage: data.statusMessage ? String(data.statusMessage).slice(0, 500) : '',
    finishedAt: data.finishedAt || null,
    httpStatus: Number(http.statusCode || 0),
  },
}];

const item = $input.first().json;
const next = { ...item };
delete next.pageRows;
delete next.dayRows;
next.offset = Number.isInteger(next.offset) ? next.offset : 0;
next.pagesFetched = next.pagesFetched || 0;
return [{ json: next }];

const http = $input.first().json;
const state = $('Prepare page').item.json;
const statusCode = Number(http.statusCode || 0);
let body = http.body;
if (typeof body === 'string') {
  try { body = JSON.parse(body); } catch (error) { body = null; }
}
let rows = [];
let decision = 'done';
let message = '';
if (statusCode && (statusCode < 200 || statusCode >= 300)) {
  decision = 'page_error';
  message = 'Dataset page request returned HTTP ' + statusCode + '. Rows already saved are kept. This workflow does not start a second actor run.';
} else if (Array.isArray(body)) {
  rows = body;
} else if (body && Array.isArray(body.items)) {
  rows = body.items;
} else if (body === null || body === undefined) {
  decision = 'page_error';
  message = 'Dataset page response was empty. This workflow does not start a second actor run.';
} else {
  decision = 'page_error';
  message = 'Dataset page response was not a list. This workflow does not start a second actor run.';
}
function headerValue(name) {
  const headers = http.headers || {};
  const found = Object.keys(headers).find((key) => key.toLowerCase() === name);
  if (!found) return null;
  const value = headers[found];
  return Array.isArray(value) ? value[0] : value;
}
const totalRaw = headerValue('x-apify-pagination-total');
const total = totalRaw === null || totalRaw === undefined || totalRaw === '' ? null : Number(totalRaw);
const pageCount = rows.length;
const nextOffset = Number(state.offset || 0) + pageCount;
const pagesFetched = Number(state.pagesFetched || 0) + 1;
let hasMore = false;
if (decision !== 'page_error') {
  if (Number.isFinite(total)) hasMore = nextOffset < total;
  else hasMore = pageCount === Number(state.pageSize);
  if (pagesFetched >= Number(state.maxPages)) hasMore = false;
  if (pageCount === 0) hasMore = false;
  decision = hasMore ? 'more' : 'done';
}
return [{
  json: {
    ...state,
    decision,
    message,
    offset: Number(state.offset || 0),
    nextOffset,
    pageCount,
    pagesFetched,
    pageRows: rows,
    fetched: Number(state.fetched || 0) + (decision === 'page_error' ? 0 : pageCount),
    partial: pagesFetched >= Number(state.maxPages) && (Number.isFinite(total) ? nextOffset < total : pageCount === Number(state.pageSize)),
  },
}];

const state = $input.first().json;
const next = { ...state };
delete next.pageRows;
next.offset = state.nextOffset;
next.decision = 'page';
return [{ json: next }];

function num(value) {
  if (value === null || value === undefined || value === '') return null;
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : null;
}
function text(value) {
  if (value === null || value === undefined) return null;
  return String(value);
}
function bool(value) {
  if (value === null || value === undefined || value === '') return null;
  return Boolean(value);
}
function carRow(car, state) {
  const badges = Array.isArray(car.badges) ? car.badges.map((badge) => String(badge)).filter(Boolean).join(', ') : null;
  return {
    vehicleId: num(car.vehicleId),
    url: text(car.url),
    make: text(car.make),
    model: text(car.model),
    year: num(car.year),
    vehicleType: text(car.vehicleType),
    rating: num(car.rating),
    completedTrips: num(car.completedTrips),
    isAllStarHost: bool(car.isAllStarHost),
    hostId: num(car.hostId),
    city: text(car.city),
    state: text(car.state),
    country: text(car.country),
    distanceMiles: num(car.distanceMiles),
    avgDailyPrice: num(car.avgDailyPrice),
    currency: text(car.currency),
    totalTripPrice: num(car.totalTripPrice),
    badges: badges || null,
    tripStart: text(car.tripStart),
    tripEnd: text(car.tripEnd),
    locationQuery: text(car.locationQuery) || state.location,
    observedAt: state.finishedAt || new Date().toISOString(),
    runId: state.runId,
  };
}

const state = { ...$input.first().json };
const cars = Array.isArray(state.cars) ? state.cars.slice() : [];
for (const car of (state.pageRows || [])) {
  if (num(car.vehicleId) === null) continue;
  cars.push(carRow(car, state));
}
return [{ json: { ...state, cars } }];

function sameMoney(left, right) {
  if (left === null && right === null) return true;
  if (left === null || right === null) return false;
  return Number(left) === Number(right);
}
const state = $('Has cars?').first().json;
const stored = $('Get stored prices').all().map((item) => item.json).filter((row) => row.observationKey);
const byKey = {};
for (const row of stored) byKey[String(row.observationKey)] = row;
const tripHasBaseline = stored.length > 0;
const output = [];
for (const car of (state.cars || [])) {
  const currency = car.currency === null || car.currency === undefined ? '' : String(car.currency);
  const tripStart = car.tripStart || (state.startDate + 'T' + (state.actorInput.startTime || '10:00'));
  const tripEnd = car.tripEnd || (state.endDate + 'T' + (state.actorInput.endTime || '10:00'));
  const observationKey = [car.vehicleId, tripStart, tripEnd, state.driverAge, currency, state.location].join('|');
  const previous = byKey[observationKey];
  let changeType = 'unchanged';
  if (!previous) changeType = tripHasBaseline ? 'new_listing' : 'baseline';
  else if (!sameMoney(previous.avgDailyPrice, car.avgDailyPrice) || !sameMoney(previous.totalTripPrice, car.totalTripPrice)) changeType = 'price_change';
  output.push({
    json: {
      observationKey,
      vehicleId: car.vehicleId === null ? null : String(car.vehicleId),
      searchStart: String(state.startDate),
      searchEnd: String(state.endDate),
      tripStart: tripStart === null ? null : String(tripStart),
      tripEnd: tripEnd === null ? null : String(tripEnd),
      driverAge: String(state.driverAge),
      locationQuery: String(state.location),
      currency: currency || null,
      avgDailyPrice: car.avgDailyPrice,
      totalTripPrice: car.totalTripPrice,
      previousAvgDailyPrice: previous ? previous.avgDailyPrice : null,
      previousTotalTripPrice: previous ? previous.totalTripPrice : null,
      changeType,
      observedAt: car.observedAt,
      make: car.make,
      model: car.model,
      year: car.year === null || car.year === undefined ? null : String(car.year),
      url: car.url,
      runId: state.runId,
    },
  });
}
return output;

const rows = $('Compare prices').all().map((item) => item.json);
const alerts = rows.filter((row) => row.changeType === 'price_change' || row.changeType === 'new_listing');
const baselines = rows.filter((row) => row.changeType === 'baseline').length;
if (!alerts.length) {
  const changeType = baselines ? 'baseline' : 'no_change';
  const message = baselines
    ? 'Saved the first price observation for this trip search. No alert rows were created.'
    : 'No average-daily or trip-total changes for the saved cars.';
  return [{ json: { changeType, alertCount: 0, baselineCount: baselines, compared: rows.length, message } }];
}
return alerts.map((row) => ({ json: row }));
